#!/bin/sh
# Builds kaggle/ft_alm/kernel.py: carries src/ft_alm.py + fold ids (filename, fold number); one fold per GPU.
# FOLDS env var picks the folds (default "0 1" = the one-fold-per-GPU test).
cd "$(dirname "$0")/.."
B64=$(base64 < src/ft_alm.py | tr -d '\n')
FOLDCSV=$(cut -d, -f1,2 cache/folds.csv | base64 | tr -d '\n')
FOLDS=${FOLDS:-"0 1"}; EPOCHS=${EPOCHS:-3}
cat > kaggle/ft_alm/kernel.py <<PY
# Kaggle kernel for Stage H (audio-LLM QLoRA fine-tuning). Generated by kaggle/build_ft_alm.sh from src/ft_alm.py.
import base64, glob, os, subprocess, sys, threading, time
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "peft", "bitsandbytes"], check=True)
import torch
from huggingface_hub import snapshot_download

OUT = "/kaggle/working"
MODEL = snapshot_download("Qwen/Qwen2-Audio-7B-Instruct")  # Apache-2.0
open("/tmp/ft_alm.py", "w").write(base64.b64decode("$B64").decode())
open("/tmp/folds.csv", "w").write(base64.b64decode("$FOLDCSV").decode())
DATA = os.path.dirname(glob.glob("/kaggle/input/**/train.csv", recursive=True)[0])
n = max(1, torch.cuda.device_count())
folds = [int(f) for f in "$FOLDS".split()]
print("GPUs:", n, [torch.cuda.get_device_name(i) for i in range(n)], "| folds", folds, flush=True)
queues = [[f for i, f in enumerate(folds) if i % n == g] for g in range(n)]
codes = {}

def run_queue(g):
    for k in queues[g]:
        r = subprocess.run([sys.executable, "/tmp/ft_alm.py", "--data", DATA, "--folds", "/tmp/folds.csv", "--out", OUT,
                            "--fold", str(k), "--model", MODEL, "--epochs", "$EPOCHS"],
                           env={**os.environ, "CUDA_VISIBLE_DEVICES": str(g)})
        codes[k] = r.returncode

t0 = time.time()
th = [threading.Thread(target=run_queue, args=(g,)) for g in range(n)]
[t.start() for t in th]; [t.join() for t in th]
print("fold exit codes:", codes, "| wall time %.0f min" % ((time.time() - t0) / 60), flush=True)
PY
echo "built kaggle/ft_alm/kernel.py (folds: $FOLDS, epochs: $EPOCHS)"
